package net.officefloor.hq.app.user;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import net.officefloor.hq.app.SignedIn;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** The signed-in user's own preferences, the same on every sheet. */
@RestController
@RequestMapping("/api/user")
@Validated
public class UserPrefController {

    /** What the screen is told about the user's locale. */
    public record LocaleView(String locale) {
    }

    /** A locale as chosen on the screen: en or de. */
    public record LocaleForm(@NotNull @Pattern(regexp = "en|de") String locale) {
    }

    private final UserPrefService service;

    public UserPrefController(UserPrefService service) {
        this.service = service;
    }

    /** The signed-in user's locale; en when they have not chosen one. */
    @GetMapping("/locale")
    public LocaleView locale(@RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user) {
        return new LocaleView(service.locale(SignedIn.name(user)));
    }

    /** Save the signed-in user's locale. */
    @PutMapping("/locale")
    public LocaleView setLocale(@RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid LocaleForm form) {
        return new LocaleView(service.setLocale(SignedIn.name(user), form.locale()));
    }
}
package net.officefloor.hq.app.user;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** A user's own preferences, kept per user name across every sheet: the locale figures are shown in. */
@Entity
@Table(name = "user_pref")
public class UserPref {

    @Id
    @Column(name = "user_name", nullable = false)
    private String userName;

    @Column(name = "locale", nullable = false)
    private String locale;

    protected UserPref() {
    }

    public UserPref(String userName, String locale) {
        this.userName = userName;
        this.locale = locale;
    }

    public String getUserName() {
        return userName;
    }

    public String getLocale() {
        return locale;
    }

    public void setLocale(String locale) {
        this.locale = locale;
    }
}
package net.officefloor.hq.app.user;

import org.springframework.data.jpa.repository.JpaRepository;

public interface UserPrefRepository extends JpaRepository<UserPref, String> {
}
package net.officefloor.hq.app.user;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** A user's own preferences: read, with en when none is saved, and saved. Not audited. */
@Service
public class UserPrefService {

    /** The locale a user has until they choose one. */
    public static final String DEFAULT_LOCALE = "en";

    private final UserPrefRepository prefs;

    public UserPrefService(UserPrefRepository prefs) {
        this.prefs = prefs;
    }

    /** The user's locale; en when they have not chosen one. */
    @Transactional(readOnly = true)
    public String locale(String user) {
        return prefs.findById(user).map(UserPref::getLocale).orElse(DEFAULT_LOCALE);
    }

    /** Save the user's locale. */
    @Transactional
    public String setLocale(String user, String locale) {
        UserPref pref = prefs.findById(user).orElseGet(() -> new UserPref(user, locale));
        pref.setLocale(locale);
        return prefs.save(pref).getLocale();
    }
}
